<div class="flex items-center justify-between">
<div class="flex items-center gap-space-sm">
<span class="w-8 h-8 rounded-lg bg-surface-container text-primary flex items-center justify-center font-bold font-display-hero text-[14px]">01</span>
<div>
<h2 class="font-headline-md text-headline-md text-on-surface font-semibold">Identitas &amp; Klasifikasi Modul</h2>
<p class="font-body-sm text-body-sm text-on-surface-variant">Konfigurasi relasi database materi dan tingkat kesulitan kurikulum.</p>
</div>
</div>
<!-- Auto-generated ERD badge -->
