<span class="material-symbols-outlined text-[16px] text-tertiary">fingerprint</span>
<span class="font-label-badge text-label-badge font-bold tracking-wide">ID: MAT-NEW-04</span>
</div>
</div>
<div class="grid grid-cols-1 md:grid-cols-2 gap-space-md">
<!-- Judul Materi -->
<div class="md:col-span-2 flex flex-col gap-space-2xs">
<label class="font-body-sm text-body-sm font-semibold text-on-surface flex items-center justify-between" for="input-judul">
<span>Judul Materi Pembelajaran <span class="text-error">*</span></span>
<span class="font-code-inline text-code-inline text-outline" id="char-counter">0/80</span>
</label>
<input class="h-10 px-space-md rounded-lg bg-surface-container-low text-on-surface font-body-md text-body-md placeholder:text-outline focus:outline-none focus:ring-2 focus:ring-secondary-container transition-all" id="input-judul" placeholder="Contoh: Logika Percabangan IF-ELSE JavaScript" type="text" value="Logika Percabangan IF-ELSE JavaScript"/>
</div>
<!-- Kategori Dropdown (ERD: kategori) -->
<div class="flex flex-col gap-space-2xs">
<label class="font-body-sm text-body-sm font-semibold text-on-surface" for="select-kategori">Kategori Materi <span class="text-error">*</span></label>
<div class="relative">
<select class="w-full h-10 pl-space-md pr-10 rounded-lg bg-surface-container-low text-on-surface font-body-md text-body-md appearance-none focus:outline-none focus:ring-2 focus:ring-secondary-container transition-all" id="select-kategori">
<option selected="" value="JavaScript Dasar">JavaScript Dasar</option>
<option value="HTML Dasar">HTML Dasar</option>
<option value="CSS Dasar">CSS Dasar</option>
