<input class="w-full h-10 pl-space-md pr-16 rounded-lg bg-surface-container-low text-on-surface font-body-md text-body-md focus:outline-none focus:ring-2 focus:ring-secondary-container transition-all" id="input-durasi" max="180" min="15" type="number" value="45"/>
<span class="absolute right-3 top-1/2 -translate-y-1/2 font-label-badge text-label-badge text-outline uppercase font-semibold">Menit</span>
</div>
</div>
<!-- Level Materi (ERD: level_Materi) -->
<div class="md:col-span-2 flex flex-col gap-space-xs pt-space-2xs">
<span class="font-body-sm text-body-sm font-semibold text-on-surface">Target Jenjang Siswa</span>
<div class="grid grid-cols-3 gap-space-sm" id="level-selector">
<label class="cursor-pointer relative flex flex-col items-center justify-center p-space-sm rounded-xl bg-surface-container text-primary font-medium text-center transition-all has-[:checked]:bg-primary-container has-[:checked]:text-on-primary-container shadow-sm">
<input checked="" class="sr-only" name="level_materi" type="radio" value="Pemula (Kelas X)"/>
<span class="font-title-sm text-title-sm font-bold">Pemula</span>
<span class="font-code-inline text-[11px] opacity-90">Fase E • Kelas X</span>
</label>
<label class="cursor-pointer relative flex flex-col items-center justify-center p-space-sm rounded-xl bg-surface-container-low text-on-surface-variant font-medium text-center transition-all hover:bg-surface-container has-[:checked]:bg-primary-container has-[:checked]:text-on-primary-container">
<input class="sr-only" name="level_materi" type="radio" value="Menengah (Kelas XI)"/>
<span class="font-title-sm text-title-sm font-bold">Menengah</span>
<span class="font-code-inline text-[11px] opacity-90">Fase F • Kelas XI</span>
</label>
<label class="cursor-pointer relative flex flex-col items-center justify-center p-space-sm rounded-xl bg-surface-container-low text-on-surface-variant font-medium text-center transition-all hover:bg-surface-container has-[:checked]:bg-primary-container has-[:checked]:text-on-primary-container">
<input class="sr-only" name="level_materi" type="radio" value="Lanjutan (Kelas XII)"/>
<span class="font-title-sm text-title-sm font-bold">Lanjutan</span>
<span class="font-code-inline text-[11px] opacity-90">Fase F • Kelas XII</span>
</label>
</div>
</div>
</div>
