<button class="text-outline hover:text-error transition-colors leading-none" type="button">×</button>
</span>
<span class="inline-flex items-center gap-space-2xs px-space-sm py-space-2xs rounded bg-surface-container-highest font-code-inline text-code-inline text-on-surface">
<span>conditional-rendering</span>
<button class="text-outline hover:text-error transition-colors leading-none" type="button">×</button>
</span>
<input class="bg-transparent font-code-inline text-code-inline text-on-surface placeholder:text-outline focus:outline-none px-space-xs flex-1 min-w-[120px]" id="tag-input" placeholder="+ tambah tag..." type="text"/>
</div>
